import sys
sys.path.insert(0, "tests")
from test_agent import POLICY_SEARCH_BASELINE as B
from tools.impl import ToolBox

tb = ToolBox()
S = {a["id"]: a for a in tb.articles}


def sc(a, q):
    ql = q.lower()
    w = {x for x in ql.replace("?", " ").split() if len(x) > 2}
    return sum(3 for k in a["keywords"] if k in ql) + sum(1 for x in w if x in a["body"].lower() or x in a["title"].lower())


def ids(q):
    return [a["id"] for a in tb.call("search_help", {"query": q})["articles"]]


for q, old in B.items():
    new = ids(q)
    if new != old:
        print(repr(q), "top_same", new[0] == old[0], [(i, sc(S[i], q)) for i in old], "->", [(i, sc(S[i], q)) for i in new])
for q in ["when is my card charged", "What is your return window?"]:
    print(q, [(i, sc(S[i], q)) for i in ids(q)])

